definition:
head_of_faith.0100 = {
	type = character_event
	title = head_of_faith.0100.t
	desc = head_of_faith.0100.desc
	theme = faith
	left_portrait = {
		character = root
		animation = personality_rational
	}
	lower_center_portrait = {
		character = scope:hof
	}

	trigger = {
		exists = faith.religious_head
	}

	immediate = {
		play_music_cue = "mx_cue_sacredrite"
		faith.religious_head = { save_scope_as = hof }
	}

	option = {
		name = head_of_faith.0100.a

		reverse_add_opinion = {
			target = scope:hof
			modifier = repentant_opinion
			opinion = 25
		}

		# No stress for faith-guiding.
		ai_chance = {
			base = 100
			opinion_modifier = {
				opinion_target = scope:hof
				multiplier = 5
			}
		}
	}

	option = {
		name = head_of_faith.0100.b

		# Plus, we flag it that this character will likely try for independence later.
		add_character_flag = wishes_to_schism_caliphate_flag
		custom_tooltip = head_of_faith.0000.wishes_to_schism_caliphate_flag_added
		# No stress for faith-guiding.
		ai_chance = {
			base = 100
			ai_value_modifier = {
				ai_vengefulness = 1
				ai_zeal = 1
			}
			opinion_modifier = {
				opinion_target = scope:hof
				multiplier = -2
			}
		}
	}
}
